// Reptile Scales - domed, glossy scales in hexagonal rows with blotchy
// markings. Parametric (u,v), static.
//
// The scales are cells of a staggered grid (odd rows shifted by half a cell),
// slightly jittered. Each scale is a dome rising from its border, tilted a
// little as overlapping scales are; the markings are a noise sampled at the
// center of each scale, so every scale takes a single color.
// SEAM-FREE: whole numbers of scales per turn and an EVEN number of rows (the
// half-cell shift alternates), wrapped indices. Twisted gluing (Klein bottle,
// Moebius band): set MIRROR_V to 1.0.
// Dock colors: u_col1 = light scales, u_col2 = dark markings and crevices.

const float COLS     = 30.0;   // scales around u (whole number)    [8 .. 60]
const float ROWS     = 24.0;   // rows around v (EVEN number)       [8 .. 60]
const float JITTER   = 0.25;   // irregularity of the scales        [0 .. 0.45]
const float DOME     = 0.30;   // width of the dome shoulder        [0.1 .. 0.5]
const float TILT     = 0.35;   // overlap tilt of every scale       [0 .. 0.8]
const float GLOSS    = 0.55;   // wet highlight                     [0 .. 1]
const float MARKINGS = 0.5;    // share of dark scales              [0 .. 1]
const float MIRROR_U = 0.0;    // 1 = fold u
const float MIRROR_V = 0.0;    // 1 = fold v (Klein bottle, Moebius band)

// ---- seam-free toolkit: every grid has a whole number of cells per turn and
// ---- every cell index is wrapped, so the pattern repeats exactly at u, v = 0/1
vec2 seamFold(vec2 q) {
    vec2 tri = 0.5 - abs(fract(q) - 0.5);   // 0 -> 0.5 -> 0: equal at both ends
    return mix(q, tri, vec2(MIRROR_U, MIRROR_V));
}

// random value of cell c, wrapped into the period n (negative indices too):
// the same cell one turn away gets the same value.
// NB: helper functions here return float/vecN only -- the per-mesh renamer of
// the engine recognizes those return types, not ivec2.
float cellHash(ivec2 c, ivec2 n, int salt) {
    ivec2 w = ivec2(mod(vec2(c), vec2(n)));
    uint h = uint(w.x) * 0x8da6b343u + uint(w.y) * 0xd8163841u + uint(salt) * 0xcb1ab31fu;
    h ^= h >> 15; h *= 0x2c1b3c6du;
    h ^= h >> 12; h *= 0x297a2d39u;
    h ^= h >> 15;
    return float(h >> 8) * (1.0 / 16777216.0);
}

vec2 cellHash2(ivec2 c, ivec2 n, int salt) {
    return vec2(cellHash(c, n, salt), cellHash(c, n, salt + 101));
}

// value noise with a period of n cells; uv in turns (0..1 = one turn)
float pnoise(vec2 uv, ivec2 n, int salt) {
    vec2 p = uv * vec2(n);
    ivec2 i = ivec2(floor(p));
    vec2 f = fract(p);
    vec2 w = f * f * (3.0 - 2.0 * f);
    float a = cellHash(i, n, salt);
    float b = cellHash(i + ivec2(1, 0), n, salt);
    float c = cellHash(i + ivec2(0, 1), n, salt);
    float d = cellHash(i + ivec2(1, 1), n, salt);
    return mix(mix(a, b, w.x), mix(c, d, w.x), w.y);
}

// fractal sum: each octave doubles the cells, so it stays periodic
float pfbm(vec2 uv, ivec2 n, int octaves, int salt) {
    float sum = 0.0;
    float amp = 0.5;
    float norm = 0.0;
    for (int o = 0; o < 6; o++) {
        if (o >= octaves) break;
        sum += amp * pnoise(uv, n, salt + 17 * o);
        norm += amp;
        amp *= 0.5;
        n *= 2;
    }
    return sum / norm;
}

// Voronoi on a grid of n cells per turn (p in cells). Returns
//   x = distance to the nearest point, y = distance to the nearest border,
//   z = random id of the nearest cell.
// rel = p minus the nearest point; edgeDir = unit vector toward the nearest
// border (the downhill direction of anything that rises from the borders).
vec3 pvoronoi(vec2 p, ivec2 n, float jitter, int salt, out vec2 rel, out vec2 edgeDir) {
    ivec2 ip = ivec2(floor(p));
    vec2 fp = fract(p);
    float best = 1.0e9;
    ivec2 bestCell = ivec2(0);
    vec2 bestPt = vec2(0.0);
    for (int j = -1; j <= 1; j++)
    for (int i = -1; i <= 1; i++) {
        ivec2 g = ivec2(i, j);
        vec2 pt = vec2(g) + 0.5 + jitter * (cellHash2(ip + g, n, salt) - 0.5);
        vec2 dv = pt - fp;
        float dd = dot(dv, dv);
        if (dd < best) { best = dd; bestCell = g; bestPt = pt; }
    }
    float border = 1.0e9;
    edgeDir = vec2(1.0, 0.0);
    for (int j = -1; j <= 1; j++)
    for (int i = -1; i <= 1; i++) {
        if (i == 0 && j == 0) continue;
        ivec2 g = bestCell + ivec2(i, j);
        vec2 pt = vec2(g) + 0.5 + jitter * (cellHash2(ip + g, n, salt) - 0.5);
        vec2 ab = pt - bestPt;
        float lab = length(ab);
        if (lab < 1.0e-5) continue;
        vec2 dir = ab / lab;
        float dist = dot(0.5 * (bestPt + pt) - fp, dir);
        if (dist < border) { border = dist; edgeDir = dir; }
    }
    rel = fp - bestPt;
    return vec3(sqrt(best), border, cellHash(ip + bestCell, n, salt + 7));
}

vec2 scalePoint(ivec2 c, ivec2 n) {
    int row = int(mod(float(c.y), float(n.y)));       // wrapped row: its parity
    float shift = 0.5 * float(row & 1);
    return vec2(c) + vec2(0.5 + shift, 0.5) + JITTER * (cellHash2(c, n, 5) - 0.5);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = seamFold(fragCoord / iResolution.xy);
    ivec2 n = ivec2(int(COLS), int(ROWS));
    vec2 p = uv * vec2(n);
    ivec2 ip = ivec2(floor(p));

    float best = 1.0e9;
    ivec2 bestCell = ip;
    vec2 bestPt = vec2(0.0);
    for (int j = -1; j <= 1; j++)
    for (int i = -1; i <= 1; i++) {
        ivec2 c = ip + ivec2(i, j);
        vec2 pt = scalePoint(c, n);
        vec2 dv = pt - p;
        float dd = dot(dv, dv);
        if (dd < best) { best = dd; bestCell = c; bestPt = pt; }
    }
    float b = 1.0e9;
    vec2 edgeDir = vec2(1.0, 0.0);
    for (int j = -1; j <= 1; j++)
    for (int i = -1; i <= 1; i++) {
        if (i == 0 && j == 0) continue;
        vec2 pt = scalePoint(bestCell + ivec2(i, j), n);
        vec2 ab = pt - bestPt;
        float lab = length(ab);
        if (lab < 1.0e-5) continue;
        vec2 dir = ab / lab;
        float dist = dot(0.5 * (bestPt + pt) - p, dir);
        if (dist < b) { b = dist; edgeDir = dir; }
    }
    vec2 rel = p - bestPt;

    // dome from the border + overlap tilt
    float x = clamp(b / DOME, 0.0, 1.0);
    float slope = 2.0 * (1.0 - x) / DOME;            // d/db of 1 - (1 - x)^2
    vec2 grad = -slope * edgeDir + vec2(0.0, -TILT);
    vec3 N = normalize(vec3(-grad * 0.22, 1.0));
    vec3 L = normalize(vec3(-0.5, 0.6, 0.8));
    float light = dot(N, L) / L.z;

    // markings: noise read at the scale center -> one color per scale
    vec2 centerUV = bestPt / vec2(n);
    float mark = pfbm(centerUV, ivec2(4, 3), 4, 21);
    float dark = smoothstep(0.62 - 0.25 * MARKINGS, 0.66 - 0.25 * MARKINGS, mark);
    float idv = cellHash(bestCell, n, 13);
    vec3 col = mix(u_col1, u_col2, dark) * (0.85 + 0.3 * idv);
    // lighter rim toward the free edge, darker crevices
    col *= light;
    float crevice = 1.0 - smoothstep(0.0, 0.08, b);
    col = mix(col, u_col2 * 0.25, 0.85 * crevice);

    // wet highlight on the domes
    vec3 R = reflect(vec3(0.0, 0.0, -1.0), N);
    float spec = pow(max(dot(R, L), 0.0), 24.0);
    col += GLOSS * spec * (1.0 - crevice) * vec3(1.0, 0.98, 0.9);

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}
